  "biology-ecology-basics": {
    "type": "process",
    "title": "Overview of Ecology Basics & Pyramids",
    "items": [
      {
        "label": "Ecology Basics & Pyramids",
        "content": "Key concept related to Ecology Basics & Pyramids",
        "color": "#10b981"
      },
      {
        "label": "1\\. Fundamental Concepts of Ecology",
        "content": "Ecology is the scientific study of interactions between organisms and their abiotic environment. It originated as a distinct discipline in the early 20th century, with seminal contributions from \\[\\[Eugenius Warming\\]\\] (1909) and \\[\\[Frederic Clements\\]\\] (1916). The term itself was coined by the German zoologist _Ernst Haeckel_ in 1866.",
        "color": "#3b82f6"
      },
      {
        "label": "2\\. Structural Components of an Ecosystem",
        "content": "An ecosystem is comprised of biotic and abiotic components that operate through complex feedback loops.",
        "color": "#f59e0b"
      },
      {
        "label": "3\\. Energy Flow in Ecosystems",
        "content": "Energy enters an ecosystem as solar radiation and exits primarily as heat following the Second Law of Thermodynamics. The pathway of energy is best visualised through the food chain and the more realistic food web.",
        "color": "#ef4444"
      },
      {
        "label": "4\\. Trophic Levels and Their Characteristics",
        "content": "Trophic levels define the position an organism occupies in a food chain.",
        "color": "#8b5cf6"
      },
      {
        "label": "5\\. Ecological Pyramids – Types and Interpretations",
        "content": "Three classic pyramids illustrate the distribution of energy, biomass, and numbers across trophic levels.",
        "color": "#06b6d4"
      },
      {
        "label": "5.1 Energy Pyramid",
        "content": "Depicts the energy flow in kilojoules per square meter per year (kJ m⁻² yr⁻¹).",
        "color": "#eab308"
      },
      {
        "label": "5.2 Biomass Pyramid",
        "content": "Represents the total mass of living material (dry weight) present in each trophic level, expressed in g m⁻² or tons km⁻².",
        "color": "#f97316"
      }
    ]
  },
